export declare const serviceConsoleStyles = "\n/* ---- \u670D\u52A1\u63A7\u5236\u53F0 ---- */\n.wf-service-console {\n  flex: none;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 6px 12px;\n  padding: 8px 12px;\n  border-bottom: 1px solid var(--wf-border);\n  background: var(--wf-layer);\n}\n\n.wf-service-console__debug {\n  flex-basis: 100%;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  border-top: 1px solid var(--wf-border);\n  padding-top: 7px;\n}\n\n.wf-service-console__debug-head {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.wf-service-console__debug-title {\n  font-size: 11px;\n  font-weight: 600;\n  color: var(--wf-ink);\n}\n\n.wf-service-console__input {\n  width: 100%;\n  resize: vertical;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 7px;\n  background: var(--wf-layer-2);\n  color: var(--wf-ink);\n  padding: 6px 8px;\n  outline: 0;\n  font: inherit;\n  font-size: 12px;\n  min-height: 44px;\n  box-sizing: border-box;\n}\n\n.wf-service-console__input:focus {\n  border-color: var(--wf-brand);\n}\n\n.wf-service-console__debug-actions {\n  display: flex;\n  gap: 7px;\n}\n\n.wf-service-console__debug-actions .wf-btn {\n  font-size: 11px;\n  padding: 4px 10px;\n}\n\n.wf-service-console__output {\n  flex: none;\n  min-height: 56px;\n  max-height: 200px;\n  overflow: auto;\n  white-space: pre-wrap;\n  word-break: break-word;\n  margin: 0;\n  padding: 8px;\n  border: 1px solid var(--wf-border);\n  border-radius: 7px;\n  background: var(--wf-layer-2);\n  color: var(--wf-ink);\n  font: inherit;\n  font-size: 12px;\n  line-height: 1.6;\n  box-sizing: border-box;\n}\n";
